import { chmod, mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { manifestFor, object, validateTask } from '../src/storage-format.js';

async function privateJSON(path, value) {
  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
  await writeFile(path, JSON.stringify(value, null, 2) + '\n', { mode: 0o600 });
  await chmod(path, 0o600);
}

// Accept a trusted independent export, NOT a manifest generated by the migration
// endpoint itself: [{key:'task:...',value:'original JSON'}] or a task object array.
export async function buildManifest(input) {
  if (!Array.isArray(input)) throw new Error('Export must be an array');
  const tasks = input.map(item => {
    if (object(item) && typeof item.key === 'string') {
      if (!item.key.startsWith('task:')) throw new Error('Unexpected export key');
      const value = typeof item.value === 'string' ? JSON.parse(item.value) : item.value;
      const id = item.key.slice(5);
      if (!object(value) || (value.id !== undefined && value.id !== id)) throw new Error('Export ID mismatch');
      return validateTask({ ...value, id });
    }
    return validateTask(item);
  });
  return { expected: await manifestFor(tasks) };
}

export async function main(args) {
  const [command, arg1, arg2] = args;
  if (command === 'manifest') {
    if (!arg1 || !arg2) throw new Error('Usage: manifest EXPORT.json MANIFEST.json [--allow-empty]');
    const result = await buildManifest(JSON.parse(await readFile(arg1, 'utf8')));
    if (!result.expected.length) {
      if (!args.includes('--allow-empty')) throw new Error('Empty export requires --allow-empty');
      result.allowEmpty = true;
    }
    await privateJSON(arg2, result);
    console.log(JSON.stringify({ written: true, taskCount: result.expected.length }));
    return;
  }

  if (!process.env.SCHEDULER_URL || !process.env.SCHEDULER_API_KEY) {
    throw new Error('SCHEDULER_URL and SCHEDULER_API_KEY are required');
  }
  const base = new URL(process.env.SCHEDULER_URL);
  if (base.protocol !== 'https:' && !(base.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(base.hostname))) {
    throw new Error('HTTPS required except for local development');
  }
  let path, body, output;
  if (command === 'status') path = '/status';
  else if (command === 'export') { path = '/export'; output = arg1; }
  else if (command === 'backup') { path = `/backup?id=${encodeURIComponent(arg1 || '')}`; output = arg2; }
  else if (command === 'prepare' || command === 'commit') {
    if (!args.includes('--source-frozen')) throw new Error('Freeze ALL legacy writers, then pass --source-frozen');
    if (!arg1 || arg1.startsWith('--')) throw new Error('Manifest file or candidate ID required');
    path = `/migration/${command}`;
    body = command === 'prepare' ? { ...JSON.parse(await readFile(arg1, 'utf8')), sourceFrozen: true } : { id: arg1, sourceFrozen: true };
  } else if (command === 'discard') { path = '/migration/discard'; body = {}; }
  else if (['rollback-prepare', 'rollback-restore', 'rollback-resume'].includes(command)) {
    path = `/rollback/${command.slice(9)}`;
    body = command === 'rollback-restore' ? { id: arg1 } : {};
  } else throw new Error('Unknown command');
  if (['export', 'backup'].includes(command) && !output) throw new Error('Private output file required');
  const response = await fetch(new URL(`/api/admin${path}`, base), {
    method: body ? 'POST' : 'GET', redirect: 'error', signal: AbortSignal.timeout(120000),
    headers: { 'X-API-Key': process.env.SCHEDULER_API_KEY, 'Content-Type': 'application/json' },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const result = await response.json();
  if (!response.ok || result.success !== true) {
    const error = new Error('Operation failed');
    error.adminStatus = response.status;
    error.adminCode = String(result.code || 'UNKNOWN').replace(/[^A-Z_]/g, '').slice(0, 64);
    throw error;
  }
  if (output) {
    await privateJSON(output, result.data);
    console.log(JSON.stringify({ written: true }));
  } else console.log(JSON.stringify(result.data, null, 2)); // Metadata only, never task configuration.
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main(process.argv.slice(2)).catch(error => {
    // Do not print fetch/parser errors: they may embed URLs or credentials.
    console.error(Number.isInteger(error.adminStatus)
      ? `Scheduler administration failed: HTTP ${error.adminStatus}, code ${error.adminCode}`
      : 'Scheduler administration failed. Check command arguments and input files.');
    process.exitCode = 1;
  });
}
